// Independent left-to-right recurrence. Uses only this review's matrix primitives.
#define main small_fixture_main
#include "independent.cpp"
#undef main
void production_guards(){rlimit c,a;getrlimit(RLIMIT_CPU,&c);getrlimit(RLIMIT_AS,&a);test(c.rlim_cur==12&&c.rlim_max==12,"CPU12");test(a.rlim_cur==256ul*1024*1024&&a.rlim_max==a.rlim_cur,"AS256");cpu_set_t set;CPU_ZERO(&set);test(sched_getaffinity(0,sizeof(set),&set)==0&&CPU_COUNT(&set)==1&&CPU_ISSET(5,&set),"CPU5");struct sigaction action;sigaction(SIGXCPU,nullptr,&action);sigset_t mask;sigprocmask(SIG_BLOCK,nullptr,&mask);test(action.sa_handler==SIG_DFL&&!sigismember(&mask,SIGXCPU),"SIGXCPU");int death;prctl(PR_GET_PDEATHSIG,&death);test(death==SIGKILL,"PDEATHSIG");std::cerr<<"POSTEXEC_CPU12_AS256_CPU5_SIGXCPU_DEFAULT_UNBLOCKED_PDEATHSIG9\n";}
int main(int argc,char**argv){try{production_guards();test(argc==3,"arguments");constexpr int L=32,Nexp=L-3;std::ifstream data(argv[1]),expected(argv[2]);int n;data>>n;test(n==11,"block count");I N,H,B;const int sizes[11]={1,8,32,80,136,162,136,80,32,8,1};for(int block=0;block<11;++block){int charge,d;data>>charge>>d;test(charge==2*block-10&&d==sizes[block],"sector");M T(d),O(d),U(d),V(d);for(auto*m:{&T,&O,&U,&V})for(auto&x:m->x)data>>x;test(bool(data),"truncated input");M P=T,R=O;int exponent=1;
 int leading=0;while((1<<(leading+1))<=Nexp)++leading;
 for(int bit=leading-1;bit>=0;--bit){M square=times(P,P);M doubled=plus(times(P,R),times(R,P),exponent%2?-1:1);P=std::move(square);R=std::move(doubled);exponent*=2;if((Nexp>>bit)&1){M next=plus(times(P,O),times(R,T),-1);P=times(P,T);R=std::move(next);++exponent;}}
 test(exponent==Nexp,"final exponent");M Pend=times(P,T),T2=times(T,T);I norm=dottrace(Pend,T2),h=L*dottrace(Pend,O),same=dottrace(Pend,U),adj=dottrace(P,V),disj=dottrace(R,O),b=L*(same-adj+disj);std::array<I,6>computed={norm,h,b,same,adj,disj};int q;expected>>q;test(q==charge,"checkpoint charge");for(const auto&value:computed){I wanted;expected>>wanted;test(bool(expected)&&wanted==value,"independent32 checkpoint mismatch");}N+=norm;H+=h;B+=b;std::cout<<"BLOCK_MATCH charge="<<charge<<" dimension="<<d<<"\n";std::cout.flush();}
 std::string extra;test(!(data>>extra)&&!(expected>>extra),"trailing data");test(N>0&&B>=0&&B<=(3*L/2)*(3*L/2)*N,"physical range");std::cout<<"N0_"<<L<<"="<<N<<"\nH0_"<<L<<"="<<H<<"\nB2_"<<L<<"="<<B<<"\nINDEPENDENT32_ALL_BLOCKS_AND_TOTALS_PASS\n";return 0;}catch(const std::exception&e){std::cerr<<"FAIL "<<e.what()<<"\n";return 2;}}
